// src/views/dreams-view-dashboard-data.ts
async function loadDashboardData(plugin, options = {}) {
  const { includeHistory = true } = options;
  const analyzer = new DreamsAnalyzer(plugin.memoryManager);
  const snapshotManager = new SnapshotManager();
  const basePath = plugin.getVaultBasePath();
  const historyPromise = includeHistory ? readDreamsRunHistory(plugin.fileAdapter, basePath, plugin.settings.engramRoot, "working") : Promise.resolve(null);
  const [report, snapshots, notes, soul, scratch, history, threadData] = await Promise.all([
    analyzer.analyze(),
    snapshotManager.list(),
    plugin.memoryManager.list(),
    plugin.memoryManager.getSoulDocument().catch(() => null),
    plugin.memoryManager.readScratch().catch(() => []),
    historyPromise,
    loadThreadData(plugin, basePath)
  ]);
  return {
    report,
    snapshotCount: snapshots.length,
    memoryNotes: notes,
    soulNote: soul,
    scratchEntries: scratch,
    threadData,
    history
  };
}
async function loadMemoryArtifacts(plugin) {
  const basePath = plugin.getVaultBasePath();
  const [notes, soul, scratch, threadData] = await Promise.all([
    plugin.memoryManager.list(),
    plugin.memoryManager.getSoulDocument().catch(() => null),
    plugin.memoryManager.readScratch().catch(() => []),
    loadThreadData(plugin, basePath)
  ]);
  return { memoryNotes: notes, soulNote: soul, scratchEntries: scratch, threadData };
}
async function loadThreadData(plugin, basePath) {
  const resolvedThreadId = await resolveActiveThreadId(plugin, basePath);
  const [threads, globalInboxItems, globalInboxSummary] = await Promise.all([
    plugin.memoryManager.listThreads().catch(() => []),
    plugin.memoryManager.listGlobalInbox().catch(() => []),
    plugin.memoryManager.getGlobalInboxSummary(resolvedThreadId ?? void 0).catch(() => null)
  ]);
  const orderedThreads = [...threads].sort((a, b) => {
    const aResolved = readThreadId(a) === resolvedThreadId ? 1 : 0;
    const bResolved = readThreadId(b) === resolvedThreadId ? 1 : 0;
    if (aResolved !== bResolved) {
      return bResolved - aResolved;
    }
    return Date.parse(readThreadUpdated(b)) - Date.parse(readThreadUpdated(a));
  });
  const slices = await Promise.all(orderedThreads.map(async (thread) => {
    const threadId = readThreadId(thread);
    const [inboxItems, threadInboxSummary] = await Promise.all([
      threadId.length > 0 ? plugin.memoryManager.listThreadInbox(threadId).catch(() => []) : Promise.resolve([]),
      threadId.length > 0 ? plugin.memoryManager.getThreadInboxSummary(threadId).catch(() => null) : Promise.resolve(null)
    ]);
    return buildThreadInfo({
      color: colorForThread(threadId),
      inboxItems,
      thread,
      threadId: threadId.length > 0 ? threadId : null,
      threadInboxSummary
    });
  }));
  return {
    globalInbox: buildGlobalInboxInfo({
      items: globalInboxItems,
      summary: globalInboxSummary
    }),
    resolvedThreadId,
    threads: slices.filter((thread) => thread.threadId.length > 0 && thread.storedCount > 0)
  };
}
async function resolveActiveThreadId(plugin, basePath) {
  try {
    const resolved = await plugin.memoryManager.resolveThread({
      cwd: basePath.length > 0 ? basePath : void 0,
      autoCreate: false
    });
    return resolved.threadId;
  } catch {
    const fallback = await loadFallbackThread(plugin);
    return fallback?.threadId ?? null;
  }
}
async function loadFallbackThread(plugin) {
  const threads = await plugin.memoryManager.listThreads().catch(() => []);
  const fallback = [...threads].filter((thread) => thread.frontmatter.status === "active" /* Active */ || thread.frontmatter.status === "paused" /* Paused */).sort((a, b) => Date.parse(readThreadUpdated(b)) - Date.parse(readThreadUpdated(a))).at(0) ?? null;
  if (fallback === null) {
    return null;
  }
  const threadId = readThreadId(fallback);
  return threadId.length > 0 ? { thread: fallback, threadId } : null;
}
function readThreadUpdated(thread) {
  return typeof thread.frontmatter.updated === "string" ? thread.frontmatter.updated : "";
}
function readThreadId(thread) {
  return typeof thread.frontmatter.thread_id === "string" ? thread.frontmatter.thread_id : "";
}

// src/utils/dream-canvas.ts
var DEFAULT_GRID_SIZE = 100;
var DEFAULT_MAX_OPACITY = 0.06;
var INITIAL_TOGGLE_MAX_MS = 150;
var TOGGLE_DELAY_MS = 25;
var NEXT_TOGGLE_MAX_MS = 200;
var FADE_SPEED = 4e-3;
var MIN_OPACITY_DELTA = 5e-4;
var OFFSET_DIVISOR = 2;
var DreamCanvas = class {
  constructor(canvas, gridSize = DEFAULT_GRID_SIZE, maxOpacity = DEFAULT_MAX_OPACITY) {
    this.canvas = canvas;
    this.gridSize = gridSize;
    this.maxOpacity = maxOpacity;
  }
  animationId = null;
  squareOpacities = [];
  targetOpacities = [];
  lastUpdateTime = 0;
  nextToggleTime = 0;
  cols = 0;
  rows = 0;
  start() {
    this.resize();
    this.resizeHandler = () => {
      this.resize();
    };
    window.addEventListener("resize", this.resizeHandler);
    this.animationId = requestAnimationFrame((t) => {
      this.animate(t);
    });
  }
  stop() {
    if (this.resizeHandler !== null) {
      window.removeEventListener("resize", this.resizeHandler);
      this.resizeHandler = null;
    }
    if (this.animationId !== null) {
      cancelAnimationFrame(this.animationId);
      this.animationId = null;
    }
  }
  resizeHandler = null;
  resize() {
    const { canvas } = this;
    const rect = canvas.getBoundingClientRect();
    const {
      width,
      height
    } = rect;
    canvas.width = width;
    canvas.height = height;
    const minDim = Math.min(canvas.width, canvas.height);
    const squareSize = Math.max(1, Math.floor(minDim / this.gridSize));
    this.cols = Math.ceil(canvas.width / squareSize);
    this.rows = Math.ceil(canvas.height / squareSize);
    const total = this.cols * this.rows;
    const {
      squareOpacities,
      targetOpacities
    } = this;
    const { length: previousLength } = squareOpacities;
    squareOpacities.length = total;
    targetOpacities.length = total;
    for (let index = previousLength; index < total; index += 1) {
      squareOpacities[index] = 0;
      targetOpacities[index] = 0;
    }
  }
  animate(time) {
    const ctx = this.canvas.getContext("2d");
    if (ctx === null) {
      return;
    }
    if (this.lastUpdateTime === 0) {
      this.lastUpdateTime = time;
      this.nextToggleTime = time + Math.random() * INITIAL_TOGGLE_MAX_MS + TOGGLE_DELAY_MS;
    }
    const delta = time - this.lastUpdateTime;
    this.lastUpdateTime = time;
    const total = this.cols * this.rows;
    if (total === 0) {
      this.requestNextFrame();
      return;
    }
    this.updateToggleTargets(time, total);
    this.interpolateSquareOpacities(total, delta);
    this.drawSquares(ctx, total);
    this.requestNextFrame();
  }
  requestNextFrame() {
    this.animationId = requestAnimationFrame((timestamp) => {
      this.animate(timestamp);
    });
  }
  updateToggleTargets(time, total) {
    if (time < this.nextToggleTime) {
      return;
    }
    const targetIndex = Math.floor(Math.random() * total);
    this.targetOpacities[targetIndex] = this.targetOpacities[targetIndex] > 0 ? 0 : this.maxOpacity;
    this.nextToggleTime = time + Math.random() * NEXT_TOGGLE_MAX_MS + TOGGLE_DELAY_MS;
  }
  interpolateSquareOpacities(total, delta) {
    const {
      squareOpacities,
      targetOpacities
    } = this;
    for (let index = 0; index < total; index += 1) {
      const currentOpacity = squareOpacities.at(index) ?? 0;
      const targetOpacity = targetOpacities.at(index) ?? 0;
      const opacityDelta = targetOpacity - currentOpacity;
      squareOpacities[index] = Math.abs(opacityDelta) > MIN_OPACITY_DELTA ? currentOpacity + opacityDelta * FADE_SPEED * delta : targetOpacity;
    }
  }
  drawSquares(ctx, total) {
    const { canvas } = this;
    const context = ctx;
    context.clearRect(0, 0, canvas.width, canvas.height);
    const minDim = Math.min(canvas.width, canvas.height);
    const squareSize = Math.max(1, Math.floor(minDim / this.gridSize));
    const offsetX = (canvas.width - this.cols * squareSize) / OFFSET_DIVISOR;
    const offsetY = (canvas.height - this.rows * squareSize) / OFFSET_DIVISOR;
    const { squareOpacities } = this;
    for (let index = 0; index < total; index += 1) {
      const opacity = squareOpacities.at(index) ?? 0;
      if (opacity <= MIN_OPACITY_DELTA) {
        continue;
      }
      const x = offsetX + index % this.cols * squareSize;
      const y = offsetY + Math.floor(index / this.cols) * squareSize;
      context.fillStyle = `rgba(255, 255, 255, ${opacity})`;
      context.fillRect(x, y, squareSize, squareSize);
    }
  }
};

// src/views/dreams-view-helpers.ts
var import_obsidian8 = require("obsidian");
